content.solution_code:
class MagicScroll {
  #mana;
  #spells;

  constructor(initialMana) {
    this.#mana = initialMana;
    this.#spells = [];
  }

  addSpell(spellName, manaCost) {
    if (manaCost <= 0) {
      console.log(`Mana cost for ${spellName} must be positive.`);
      return;
    }
    this.#spells.push({ name: spellName, manaCost: manaCost });
    console.log(`${spellName} added to the scroll.`);
  }

  castSpell(spellName) {
    const spell = this.#spells.find(s => s.name === spellName);

    if (!spell) {
      console.log(`Spell "${spellName}" not found on this scroll.`);
      return false; // Early return for unknown spell
    }

    if (this.#mana < spell.manaCost) {
      console.log(`Not enough mana to cast "${spellName}". Requires ${spell.manaCost}, but only ${this.#mana} available.`);
      return false; // Early return for insufficient mana
    }

    this.#mana -= spell.manaCost;
    console.log(`Successfully cast "${spellName}". Remaining mana: ${this.#mana}`);
    return true;
  }

  getMana() {
    return this.#mana;
  }
}

